PROCEDURE @@proc@@ (p_groups IN PLS_INTEGER) IS
BEGIN
    <<outer>>
    FOR g IN 1 .. p_groups LOOP
        <<inner>>
        FOR rec IN (SELECT @@col@@ FROM @@tab@@ WHERE grp = g) LOOP
            @@proc2@@(rec.@@col@@);
        END LOOP inner;
        COMMIT; -- @expect
    END LOOP outer;
    COMMIT;
END @@proc@@;

PROCEDURE @@proc@@ (p_n IN PLS_INTEGER) IS
    l_i PLS_INTEGER := 0;
BEGIN
    WHILE l_i < p_n LOOP
        l_i := l_i + 1;
        @@proc2@@(l_i);
        -- END LOOP; (the loop continues below)
        DBMS_OUTPUT.PUT_LINE('END LOOP;');
        /* END LOOP; */ COMMIT; -- @expect
    END LOOP;
END @@proc@@;

PROCEDURE @@proc@@ (p_ids IN SYS.ODCINUMBERLIST) IS
    l_ok BOOLEAN;
BEGIN
    FOR i IN 1 .. p_ids.COUNT LOOP
        CONTINUE WHEN p_ids(i) IS NULL;
        @@proc2@@(p_ids(i), l_ok);
        IF l_ok THEN
            IF p_ids(i) > @@num@@ THEN
                NULL;
            END IF;
        ELSIF p_ids(i) < 0 THEN
            ROLLBACK; -- @expect
        END IF;
        EXIT WHEN i >= @@num2@@;
    END LOOP;
END @@proc@@;

PROCEDURE @@proc@@ (p_n IN PLS_INTEGER) IS
    PROCEDURE flush_all IS
    BEGIN
        COMMIT;
    END flush_all;
BEGIN
    FOR i IN 1 .. p_n LOOP
        @@proc2@@(i);
        COMMIT -- @expect
            WORK;
    END LOOP;
    flush_all;
END @@proc@@;

PROCEDURE @@proc@@ (p_n IN PLS_INTEGER) IS
BEGIN
    FOR i IN 1 .. p_n LOOP
        @@proc2@@(i);
        $IF $$autocommit $THEN
            COMMIT; -- @expect
        $ELSE
            NULL;
        $END
    END LOOP;
    @@proc2@@(0);
END @@proc@@;

