PROCEDURE @@proc@@ (p_n IN PLS_INTEGER) IS
    l_commit_count PLS_INTEGER := 0;
    l_msg VARCHAR2(100);
BEGIN
    FOR i IN 1 .. p_n LOOP
        -- do not COMMIT; here, the caller does
        l_msg := 'commit; rollback;';
        l_commit_count := l_commit_count + 1;
        /* ROLLBACK; */
        UPDATE @@tab@@ SET "COMMIT" = l_commit_count WHERE id = i;
        @@proc2@@(i, l_msg);
    END LOOP;
    COMMIT;
END @@proc@@;

PROCEDURE @@proc@@ (p_mode IN VARCHAR2, p_n IN PLS_INTEGER) IS
BEGIN
    IF p_mode = 'PRE' THEN
        COMMIT;
    END IF;
    FOR i IN 1 .. p_n LOOP
        CASE
            WHEN MOD(i, 2) = 0 THEN
                @@proc2@@(i);
            ELSE
                NULL;
        END CASE;
        EXIT WHEN i > @@num@@;
    END LOOP;
    COMMIT;
END @@proc@@;

PROCEDURE @@proc@@ (p_n IN PLS_INTEGER) IS
    PROCEDURE save_it IS
    BEGIN
        COMMIT;
    END save_it;
BEGIN
    FOR i IN 1 .. p_n LOOP
        @@proc2@@(i);
        save_it;
    END LOOP;
END @@proc@@;

PROCEDURE @@proc@@ (p_ids IN SYS.ODCINUMBERLIST) IS
BEGIN
    FOR i IN 1 .. p_ids.COUNT LOOP
        SAVEPOINT sp_item;
        BEGIN
            @@proc2@@(p_ids(i));
        EXCEPTION
            WHEN VALUE_ERROR THEN
                ROLLBACK
                    TO sp_item;
            WHEN DUP_VAL_ON_INDEX THEN
                ROLLBACK TO SAVEPOINT sp_item;
        END;
    END LOOP;
    ROLLBACK;
END @@proc@@;

PROCEDURE @@proc@@ (p_n IN PLS_INTEGER) IS
BEGIN
    BEGIN
        FOR i IN 1 .. p_n LOOP
            @@proc2@@(i);
        END LOOP;
    EXCEPTION
        WHEN VALUE_ERROR THEN
            ROLLBACK;
    END;
    COMMIT;
END @@proc@@;
